✅ Addressed in commit e452687

Maybe one topic to consider is implementing assertions using an interface with default methods, similar to AssertJ's `WithAssertions`. This approach makes it easy to integrate assertions and supports a form of multiple inheritance.

That said, it was just an initial idea. I'm also perfectly fine with using a class instead—it really depends on the context and specific needs.

Below is a quick prototype I put together. I had forgotten that I even created one:

```java
package org.operaton.bpm.engine.test.util;

import org.awaitility.Awaitility;
import org.awaitility.core.ConditionTimeoutException;
import org.operaton.bpm.BpmPlatform;
import org.operaton.bpm.engine.ManagementService;
import org.operaton.bpm.engine.ProcessEngine;
import org.operaton.bpm.engine.ProcessEngineException;
import org.operaton.bpm.engine.impl.ProcessEngineImpl;
import org.operaton.bpm.engine.impl.cfg.ProcessEngineConfigurationImpl;
import org.operaton.bpm.engine.impl.jobexecutor.JobExecutor;
import org.operaton.bpm.engine.impl.jobexecutor.ThreadPoolJobExecutor;

import java.util.Optional;
import java.util.concurrent.Callable;
import java.util.concurrent.TimeUnit;

public interface WithJobExecutorAssertions {

    long DEFAULT_TIMEOUT = 20000L;
    long DEFAULT_CHECK_INTERVAL = 500L;
    boolean DEFAULT_SHUTDOWN_AFTER_PROCESSING = true;

    default JobExecutorAssert assertThatJobExecutor() {
        return new JobExecutorAssert();
    }

    default ConditionAwaitAssert assertThatCondition() {
        return new ConditionAwaitAssert();
    }

    class AwaitConfiguration {
        private long timeoutMillis = DEFAULT_TIMEOUT;
        private long pollIntervalMillis = DEFAULT_CHECK_INTERVAL;
        private boolean ignoreExceptions = DEFAULT_SHUTDOWN_AFTER_PROCESSING;

        public long getTimeoutMillis() {
            return timeoutMillis;
        }

        public AwaitConfiguration withTimeoutMillis(long timeoutMillis) {
            this.timeoutMillis = timeoutMillis;
            return this;
        }

        public long getPollIntervalMillis() {
            return pollIntervalMillis;
        }

        public AwaitConfiguration withPollIntervalMillis(long pollIntervalMillis) {
            this.pollIntervalMillis = pollIntervalMillis;
            return this;
        }

        public boolean isIgnoreExceptions() {
            return ignoreExceptions;
        }

        public AwaitConfiguration withIgnoreExceptions(boolean ignoreExceptions) {
            this.ignoreExceptions = ignoreExceptions;
            return this;
        }
    }

    class JobExecutorAssert {
        private static final int JOB_EXECUTOR_WAIT_MULTIPLIER = 2;

        private String processInstanceId;
        private final AwaitConfiguration config = new AwaitConfiguration();

        private boolean shutdownAfterProcessing = DEFAULT_SHUTDOWN_AFTER_PROCESSING;
        private JobExecutor jobExecutor;
        private ManagementService managementService;
        private ProcessEngine processEngine;
        private ConditionAwaitAssert conditionAwaitAssert;

        public JobExecutorAssert withProcessEngine(ProcessEngine processEngine) {
            this.processEngine = processEngine;
            return this;
        }

        public JobExecutorAssert withProcessInstance(String processInstanceId) {
            this.processInstanceId = processInstanceId;
            return this;
        }

        public JobExecutorAssert withTimeout(long timeoutMillis) {
            config.withTimeoutMillis(timeoutMillis);
            return this;
        }

        public JobExecutorAssert withCheckInterval(long intervalMillis) {
            config.withPollIntervalMillis(intervalMillis);
            return this;
        }

        public JobExecutorAssert shutdownExecutorAfter(boolean shutdownAfterProcessing) {
            this.shutdownAfterProcessing = shutdownAfterProcessing;
            return this;
        }

        public ConditionAwaitAssert condition() {
            if (conditionAwaitAssert == null) {
                conditionAwaitAssert = new ConditionAwaitAssert(config);
            }
            return conditionAwaitAssert;
        }

        public void waitForAllJobsToBeProcessed() {
            initializeProcessEngineComponents();
            calculateMaxWaitTime();
            activateJobExecutor();
            Callable<Boolean> condition = () -> !areJobsAvailable();
            try {
                new ConditionAwaitAssert(config).until(condition);
            } catch (Exception e) {
                throw new ProcessEngineException("Time limit of " + config.getTimeoutMillis() + " was exceeded (still "
                        + numberOfJobsAvailable() + " jobs available)", e);
            } finally {
                shutdownJobExecutor();
            }
        }

        private void shutdownJobExecutor() {
            if (shutdownAfterProcessing && jobExecutor.isActive()) {
                jobExecutor.shutdown();
            }
        }

        private void initializeProcessEngineComponents() {
            if (processEngine == null) {
                processEngine = getDefaultProcessEngine();
            }
            ProcessEngineConfigurationImpl engineConfig = ((ProcessEngineImpl) processEngine).getProcessEngineConfiguration();
            jobExecutor = engineConfig.getJobExecutor();
            managementService = engineConfig.getManagementService();
        }

        private void calculateMaxWaitTime() {
            int jobExecutorWaitTime = jobExecutor.getWaitTimeInMillis() * JOB_EXECUTOR_WAIT_MULTIPLIER;
            if (config.getTimeoutMillis() < jobExecutorWaitTime) {
                config.withTimeoutMillis(jobExecutorWaitTime);
            }
        }

        private void activateJobExecutor() {
            if (!jobExecutor.isActive()) {
                jobExecutor.start();
            }
        }

        private ProcessEngine getDefaultProcessEngine() {
            return BpmPlatform.getProcessEngineService().getDefaultProcessEngine();
        }

        private boolean areJobsAvailable() {
            return numberOfJobsAvailable() > 0;
        }

        private long numberOfJobsAvailable() {
            return Optional.ofNullable(processInstanceId)
                    .map(piId -> managementService.createJobQuery().processInstanceId(piId))
                    .orElse(managementService.createJobQuery())
                    .withRetriesLeft()
                    .executable()
                    .active()
                    .count();
        }
    }

    class JobExecutionRunnablesAssert {
        private static final int THREAD_POOL_ACTIVE_COUNT_ZERO = 0;
        private final AwaitConfiguration config = new AwaitConfiguration();
        private ThreadPoolJobExecutor jobExecutor;

        public JobExecutionRunnablesAssert withProcessEngine(ProcessEngine processEngine) {
            ProcessEngineConfigurationImpl cfg = ((ProcessEngineImpl) processEngine).getProcessEngineConfiguration();
            this.jobExecutor = (ThreadPoolJobExecutor) cfg.getJobExecutor();
            return this;
        }

        public JobExecutionRunnablesAssert withTimeout(long timeoutMillis) {
            config.withTimeoutMillis(timeoutMillis);
            return this;
        }

        public JobExecutionRunnablesAssert withCheckInterval(long intervalMillis) {
            config.withPollIntervalMillis(intervalMillis);
            return this;
        }

        public void areFinished() {

            try {
                new ConditionAwaitAssert(config).until(() -> jobExecutor.getThreadPoolExecutor().getActiveCount() == THREAD_POOL_ACTIVE_COUNT_ZERO);
            } catch (Exception e) {
                throw new ProcessEngineException("Active job executor threads not finished after " + config.getTimeoutMillis() + " ms", e);
            }
        }
    }

    class ConditionAwaitAssert {
        private final AwaitConfiguration config;

        public ConditionAwaitAssert() {
            this.config = new AwaitConfiguration();
        }

        public ConditionAwaitAssert(AwaitConfiguration config) {
            this.config = config;
        }

        public ConditionAwaitAssert withTimeout(long timeoutMillis) {
            config.withTimeoutMillis(timeoutMillis);
            return this;
        }

        public ConditionAwaitAssert withCheckInterval(long intervalMillis) {
            config.withPollIntervalMillis(intervalMillis);
            return this;
        }

        public ConditionAwaitAssert ignoreExceptions() {
            config.withIgnoreExceptions(true);
            return this;
        }

        public void until(Callable<Boolean> condition) {
            long timeout = config.getTimeoutMillis();
            long pollInterval = config.getPollIntervalMillis();

            if (timeout < pollInterval) {
                pollInterval = timeout;
            }

            try {
                Awaitility.await()
                        .atMost(timeout, TimeUnit.MILLISECONDS)
                        .pollInterval(pollInterval, TimeUnit.MILLISECONDS)
                        .ignoreExceptionsMatching(e -> config.isIgnoreExceptions())
                        .until(condition);
            } catch (ConditionTimeoutException e) {
                throw new ProcessEngineException("Condition was not met within " + timeout + " ms", e);
            }
        }
    }
}

```

